// The offline app's core: find the page for an address, run it (with its layouts) like the server
// would, and answer /api/… requests with the site's own route handlers.
import { createElement, type ReactNode } from 'react'
// @ts-expect-error generated by scripts/offline/build-offline-app.mjs
import { pages, apis } from 'offline-routes'
import { resolveNode } from './resolve'
import { NotFoundError, RedirectError } from './shims/next-navigation'

type Key = { name: string; rest: boolean }
type Route = { path: string; re: RegExp; keys: Key[]; load: () => Promise<any>; layouts?: (() => Promise<any>)[] }

function match(list: Route[], pathname: string) {
  for (const r of list) {
    const m = r.re.exec(pathname)
    if (!m) continue
    const params: Record<string, string | string[]> = {}
    r.keys.forEach((k, i) => { const v = decodeURIComponent(m[i + 1]); params[k.name] = k.rest ? v.split('/') : v })
    return { route: r, params }
  }
  return null
}

export function matchPage(pathname: string) { return match(pages as Route[], pathname) }

const searchObject = (sp: URLSearchParams) => {
  const o: Record<string, string | string[]> = {}
  for (const k of new Set(sp.keys())) { const all = sp.getAll(k); o[k] = all.length > 1 ? all : all[0] }
  return o
}

export type Rendered =
  | { kind: 'page'; node: ReactNode; title: string | null; params: Record<string, string | string[]> }
  | { kind: 'notfound' } | { kind: 'redirect'; url: string } | { kind: 'unavailable' }

export async function renderPage(pathname: string, search: URLSearchParams): Promise<Rendered> {
  const found = matchPage(pathname)
  if (!found) return { kind: 'unavailable' }
  const { route, params } = found
  try {
    const mod = await route.load()
    const props = { params: Promise.resolve(params), searchParams: Promise.resolve(searchObject(search)) }
    let title: string | null = null
    try {
      const meta = mod.generateMetadata ? await mod.generateMetadata(props) : mod.metadata
      const t = meta?.title
      title = typeof t === 'string' ? t : t?.absolute ?? t?.default ?? null
    } catch {}
    let tree: ReactNode = createElement(mod.default, props)
    const layouts = await Promise.all((route.layouts ?? []).map(l => l()))
    for (const l of layouts.reverse()) tree = createElement(l.default, { params: props.params }, tree)
    const node = await resolveNode(tree)
    return { kind: 'page', node, title, params }
  } catch (e) {
    if (e instanceof NotFoundError) return { kind: 'notfound' }
    if (e instanceof RedirectError) return { kind: 'redirect', url: e.url }
    throw e
  }
}

/** /api/… answered by the site's route handler, or null when the offline app has none */
export async function handleApi(url: URL, init?: RequestInit): Promise<Response | null> {
  const found = match(apis as Route[], url.pathname)
  if (!found) return null
  const mod = await found.route.load()
  const method = (init?.method || 'GET').toUpperCase()
  const handler = mod[method]
  if (!handler) return new Response('Method not allowed', { status: 405 })
  const req = new Request(url, init) as Request & { nextUrl?: URL }
  Object.defineProperty(req, 'nextUrl', { value: url })
  return handler(req, { params: Promise.resolve(found.params) })
}
